aim_type": "customer", "evidence_status": "needs_validation", "source_ids": [], "content_anchor": "Addressing the reported relatively low perception of AI benefits in education among the US public (some reports suggest only 39% consider it beneficial) and the adoption gap among higher education faculty (with some data indicating only 22% regularly use generative AI compared to 83% of K-12 teachers) will be critical."}, {"text": "It has been reported that all 50 US states have introduced legislation on AI, and federal executive orders have established a national framework for AI in education.", "claim_type": "regulatory", "evidence_status": "needs_validation", "source_ids": [], "content_anchor": "It has been reported that all 50 US states have introduced legislation on AI, and federal executive orders have established a national framework for AI in education."}], "source_ids": [], "confidence": "low"}}
